edges = {'A': [('B', 3), ('C', 8), ('D', 20)], 'B': [('C', 2), ('D', 9)], 'C': [('D', 4)], 'D': []}
ways = {v: 0 for v in edges}
ways['A'] = 1
for v in ['A', 'B', 'C', 'D']:
    for to, weight in edges[v]:
        ways[to] += ways[v]
print(ways['D'])

edges = {'A': [('B', 3), ('C', 8)], 'B': [('D', 9)], 'C': [('D', 4)], 'D': []}
dist = {v: float('inf') for v in edges}
dist['A'] = 0
for v in ['A', 'B', 'C', 'D']:
    for to, weight in edges[v]:
        dist[to] = min(dist[to], dist[v]+weight)
print(dist['D'])

edges = {'A': [('B', 3), ('C', 8)], 'B': [('C', 2), ('D', 9)], 'C': [('D', 4)], 'D': []}
dist = {v: float('-inf') for v in edges}
dist['A'] = 0
for v in ['A', 'B', 'C', 'D']:
    for to, weight in edges[v]:
        dist[to] = max(dist[to], dist[v]+weight)
print(dist['D'])
